            const images = document.querySelectorAll('img');
            images.forEach(img => {
              if (img.complete) {
                checkAllImagesLoaded();
              } else {
                img.onload = checkAllImagesLoaded;
                img.onerror = checkAllImagesLoaded;
              }
            });

            setTimeout(() => {
              if (imagesLoaded < totalImages) {
                window.print();
              }
            }, 3000);
